import{_ as a,o as e,c as d,a5 as o}from"./chunks/framework.BEZBAInb.js";const b=JSON.parse('{"title":"演員切換狀態","description":"","frontmatter":{"title":"演員切換狀態","order":4},"headers":[],"relativePath":"tc/latest/tutorial/script/actor/actor-change-state.md","filePath":"tc/latest/tutorial/script/actor/actor-change-state.md","lastUpdated":1788455378000}'),r={name:"tc/latest/tutorial/script/actor/actor-change-state.md"};function i(c,t,s,n,l,h){return e(),d("div",null,[...t[0]||(t[0]=[o('<h1 id="演員切換狀態" tabindex="-1">演員切換狀態 <a class="header-anchor" href="#演員切換狀態" aria-label="Permalink to &quot;演員切換狀態&quot;">​</a></h1><h2 id="功能描述" tabindex="-1">功能描述 <a class="header-anchor" href="#功能描述" aria-label="Permalink to &quot;功能描述&quot;">​</a></h2><p>切換指定演員的狀態。能安全提供狀態影格的角色會進行新舊畫面交融；其他角色會自動使用淡出、套用狀態、淡入的安全轉場。轉場完成後繼續執行劇情。</p><h2 id="語法結構" tabindex="-1">語法結構 <a class="header-anchor" href="#語法結構" aria-label="Permalink to &quot;語法結構&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>actor change &lt;角色名稱&gt; &lt;新狀態&gt;</span></span></code></pre></div><h2 id="參數詳解" tabindex="-1">參數詳解 <a class="header-anchor" href="#參數詳解" aria-label="Permalink to &quot;參數詳解&quot;">​</a></h2><table tabindex="0"><thead><tr><th>參數</th><th>必需</th><th>範例</th><th>說明</th></tr></thead><tbody><tr><td>角色</td><td>是</td><td>kona</td><td>指定要切換狀態的演員名稱</td></tr><tr><td>新狀態</td><td>是</td><td>happy</td><td>指定要切換到的新狀態</td></tr></tbody></table><h2 id="範例" tabindex="-1">範例 <a class="header-anchor" href="#範例" aria-label="Permalink to &quot;範例&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>actor change kona happy</span></span></code></pre></div><h2 id="狀態切換轉場" tabindex="-1">狀態切換轉場 <a class="header-anchor" href="#狀態切換轉場" aria-label="Permalink to &quot;狀態切換轉場&quot;">​</a></h2><p><code>actor change</code> 會自動選擇轉場方式：</p><ol><li>角色場景能提供目前與目標狀態影格時，使用預乘 Alpha shader 進行像素交融。</li><li>無法安全提供狀態影格時，依序淡出目前角色、套用狀態並淡入。</li><li>轉場結束後，繼續執行下一條劇情指令。</li></ol><p>可以在 <code>KonadoStageController</code> 節點的屬性面板中設定轉場：</p><table tabindex="0"><thead><tr><th>屬性</th><th>預設值</th><th>說明</th></tr></thead><tbody><tr><td><code>actor_state_transition_enabled</code></td><td><code>true</code></td><td>是否為演員狀態切換啟用淡入淡出</td></tr><tr><td><code>actor_state_transition_duration</code></td><td><code>0.3</code></td><td>完整轉場的總時長（秒）；安全降級時淡出和淡入各占一半</td></tr></tbody></table><p>關閉 <code>actor_state_transition_enabled</code> 或將 <code>actor_state_transition_duration</code> 設為 <code>0</code> 時，狀態會立即切換。</p><p>轉場不會複製角色場景。內建 AnimatedSprite2D 範例透過純紋理狀態影格實現真正交融；自訂狀態影格必須完整表示角色畫面，不能只包含其中一個可見元件。影片、Spine、Live2D 和無法提供完整安全狀態影格的自訂角色場景會自動降級，不會重複執行腳本、音訊或動態媒體。找不到目標演員或角色場景無法套用該狀態時，系統會結束本次指令並繼續劇情，不會持續等待。</p>',16)])])}const u=a(r,[["render",i]]);export{b as __pageData,u as default};
